cat > spec/list_room.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-01)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with a date"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" ] || { echo "list --room with a date that has no booking should print nothing"; fail=1; }
BOOKINGS=$t bash src/list.sh --room >/dev/null 2>&1; [ $? = 2 ] || { echo "--room without a value should exit 2"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash spec/list_room.spec.sh; echo "list_room exit $?"; bash tools/check; echo "check exit $?"; bash tools/lint; echo "lint exit $?"; tail -3 var/check-runs.log

